PRAGMA foreign_keys = ON;
CREATE TABLE address_zones(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,approved INTEGER NOT NULL CHECK(approved IN(0,1)));
CREATE TABLE students(id TEXT PRIMARY KEY,name TEXT NOT NULL,zone_id TEXT NOT NULL REFERENCES address_zones(id),needs_accessible_bus INTEGER NOT NULL,preferred_stop_id TEXT REFERENCES stops(id),max_wait_minutes INTEGER NOT NULL DEFAULT 30 CHECK(max_wait_minutes>0),safety_restriction TEXT,status TEXT NOT NULL CHECK(status IN('active','inactive')));
CREATE TABLE guardian_contacts(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),phone TEXT NOT NULL,valid INTEGER NOT NULL CHECK(valid IN(0,1)));
CREATE TABLE stops(id TEXT PRIMARY KEY,name TEXT NOT NULL,zone_id TEXT NOT NULL REFERENCES address_zones(id),approved INTEGER NOT NULL CHECK(approved IN(0,1)),restricted INTEGER NOT NULL DEFAULT 0 CHECK(restricted IN(0,1)));
CREATE TABLE buses(id TEXT PRIMARY KEY,capacity INTEGER NOT NULL CHECK(capacity>0),accessible INTEGER NOT NULL,lifecycle TEXT NOT NULL CHECK(lifecycle IN('active','maintenance','retired')),available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)));
CREATE TABLE drivers(id TEXT PRIMARY KEY,name TEXT NOT NULL,license_status TEXT NOT NULL CHECK(license_status IN('active','suspended')),available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)));
CREATE TABLE routes(id TEXT PRIMARY KEY,bus_id TEXT NOT NULL REFERENCES buses(id),driver_id TEXT REFERENCES drivers(id),status TEXT NOT NULL CHECK(status IN('active','disrupted','inactive')));
CREATE TABLE route_stops(route_id TEXT REFERENCES routes(id),stop_id TEXT REFERENCES stops(id),sequence INTEGER NOT NULL CHECK(sequence>0),pickup_window TEXT NOT NULL,distance_km REAL NOT NULL DEFAULT 0,wait_minutes INTEGER NOT NULL DEFAULT 15,PRIMARY KEY(route_id,stop_id),UNIQUE(route_id,sequence));
CREATE TABLE assignments(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),route_id TEXT NOT NULL REFERENCES routes(id),stop_id TEXT NOT NULL REFERENCES stops(id),effective_from DATE NOT NULL,effective_to DATE,status TEXT NOT NULL CHECK(status IN('active','ended')),allocation_score REAL,allocation_explanation TEXT);
CREATE TABLE assignment_events(id INTEGER PRIMARY KEY AUTOINCREMENT,assignment_id TEXT NOT NULL REFERENCES assignments(id),event_type TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,detail TEXT NOT NULL);
CREATE TABLE attendance_events(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT NOT NULL REFERENCES students(id),event_date DATE NOT NULL,status TEXT NOT NULL CHECK(status IN('boarded','absent','missed_pickup')));
CREATE TABLE notifications(id TEXT PRIMARY KEY,contact_id TEXT NOT NULL REFERENCES guardian_contacts(id),event_type TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','sent','blocked')));
CREATE TABLE data_issues(id INTEGER PRIMARY KEY AUTOINCREMENT,issue_type TEXT NOT NULL,entity_ref TEXT NOT NULL,ground_truth TEXT NOT NULL);
CREATE TABLE app_users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','driver','parent')),display_name TEXT NOT NULL,driver_id TEXT REFERENCES drivers(id),guardian_id TEXT REFERENCES guardian_contacts(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES app_users(id),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL);
CREATE TABLE trips(id TEXT PRIMARY KEY,route_id TEXT NOT NULL REFERENCES routes(id),driver_id TEXT NOT NULL REFERENCES drivers(id),service_date DATE NOT NULL,status TEXT NOT NULL CHECK(status IN('not_started','in_progress','completed')),current_stop_id TEXT REFERENCES stops(id),started_at DATETIME,completed_at DATETIME,UNIQUE(route_id,service_date));
CREATE TABLE bus_locations(id INTEGER PRIMARY KEY AUTOINCREMENT,route_id TEXT NOT NULL REFERENCES routes(id),driver_id TEXT NOT NULL REFERENCES drivers(id),latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy_meters REAL,recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student_trip_events(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id TEXT NOT NULL REFERENCES trips(id),student_id TEXT NOT NULL REFERENCES students(id),route_id TEXT NOT NULL REFERENCES routes(id),driver_id TEXT NOT NULL REFERENCES drivers(id),event_type TEXT NOT NULL CHECK(event_type IN('boarded','absent','dropped_off')),stop_id TEXT REFERENCES stops(id),latitude REAL,longitude REAL,note TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
